import React, { useState, useEffect } from "react";
import axios from "axios";
import { ethers } from "ethers";
import "./WalletSetup.css";

const WalletSetup = ({ walletAddress, onReady, API_BASE, headers }) => {
  const [requirements, setRequirements] = useState(null);
  const [balances, setBalances] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [step, setStep] = useState(0);

  const STEPS = [
    "Check Wallet",
    "Add Network",
    "Add USDC Token",
    "Get Test Tokens",
    "Ready!"
  ];

  useEffect(() => {
    if (walletAddress) {
      checkRequirements();
    }
  }, [walletAddress]);

  const checkRequirements = async () => {
    try {
      setLoading(true);
      const res = await axios.post(
        `${API_BASE}/wallet/check-requirements`,
        { wallet_address: walletAddress },
        { headers }
      );

      setRequirements(res.data.requirements);
      
      // Get current balances
      const balanceRes = await axios.get(
        `${API_BASE}/wallet/balances/${walletAddress}`,
        { headers }
      );
      setBalances(balanceRes.data);

      if (res.data.requirements.ready_to_purchase) {
        setStep(4);
        onReady?.(true);
      } else {
        setStep(0);
        onReady?.(false);
      }
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const addNetwork = async () => {
    try {
      setLoading(true);
      const netRes = await axios.get(`${API_BASE}/wallet/network-config`, { headers });
      const networkConfig = netRes.data.network.config;

      await window.ethereum.request({
        method: "wallet_addEthereumChain",
        params: [networkConfig],
      });

      setStep(2);
      setTimeout(checkRequirements, 1000);
    } catch (err) {
      if (err.code !== 4001) { // User rejected
        setError(`Failed to add network: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const addUSDC = async () => {
    try {
      setLoading(true);
      const netRes = await axios.get(`${API_BASE}/wallet/network-config`, { headers });
      const usdcConfig = netRes.data.usdc.config;

      await window.ethereum.request({
        method: "wallet_watchAsset",
        params: {
          type: "ERC20",
          options: {
            address: usdcConfig.address,
            symbol: usdcConfig.symbol,
            decimals: usdcConfig.decimals,
            image: usdcConfig.image,
          },
        },
      });

      setStep(3);
      setTimeout(checkRequirements, 1000);
    } catch (err) {
      if (err.code !== 4001) {
        setError(`Failed to add USDC: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const getFaucetLinks = async () => {
    try {
      const res = await axios.get(`${API_BASE}/wallet/faucets`, { headers });
      return res.data;
    } catch (err) {
      return null;
    }
  };

  if (loading) {
    return <div className="wallet-setup loading">Checking wallet requirements...</div>;
  }

  if (!requirements) {
    return <div className="wallet-setup error">Failed to check wallet: {error}</div>;
  }

  const { avax, usdc, ready_to_purchase, issues } = requirements;

  return (
    <div className="wallet-setup">
      <div className="setup-header">
        <h2>🔐 Wallet Setup</h2>
        <div className="setup-steps">
          {STEPS.map((s, i) => (
            <div
              key={i}
              className={`step ${i === step ? "active" : i < step ? "completed" : ""}`}
            >
              {i < step ? "✓" : i + 1}
            </div>
          ))}
        </div>
      </div>

      {/* Current Balances */}
      {balances && (
        <div className="balances-section">
          <h3>💰 Current Balances</h3>
          <div className="balance-cards">
            <div className={`balance-card ${avax.sufficient ? "sufficient" : "insufficient"}`}>
              <div className="token-name">AVAX (Gas)</div>
              <div className="balance-amount">{avax.balance.toFixed(4)} AVAX</div>
              {!avax.sufficient && (
                <div className="need-more">Need: {avax.needs.toFixed(4)} more</div>
              )}
              {avax.sufficient && <div className="status-ok">✓ Sufficient</div>}
            </div>

            <div className={`balance-card ${usdc.sufficient ? "sufficient" : "insufficient"}`}>
              <div className="token-name">USDC (Payments)</div>
              <div className="balance-amount">${usdc.balance.toFixed(2)}</div>
              {!usdc.sufficient && (
                <div className="need-more">Need: ${usdc.needs.toFixed(2)} more</div>
              )}
              {usdc.sufficient && <div className="status-ok">✓ Sufficient</div>}
            </div>
          </div>
        </div>
      )}

      {/* Issues & Setup Steps */}
      {issues.length > 0 && (
        <div className="issues-section">
          <h3>⚠️ Setup Required</h3>
          
          {issues.some(i => i.type === "insufficient_avax") && (
            <div className="issue-block avax-issue">
              <h4>Need Test AVAX for Gas Fees</h4>
              <p>Use one of these faucets to get free AVAX:</p>
              <button
                onClick={() => window.open("https://faucet.avax.network/", "_blank")}
                className="faucet-btn"
              >
                🚰 Avalanche Faucet
              </button>
              <button
                onClick={() => window.open("https://www.alchemy.com/faucets/avalanche-fuji", "_blank")}
                className="faucet-btn"
              >
                🍺 Alchemy Faucet
              </button>
              <p className="hint">Request 2-10 AVAX to cover transaction costs</p>
            </div>
          )}

          {issues.some(i => i.type === "insufficient_usdc") && (
            <div className="issue-block usdc-issue">
              <h4>Need Test USDC for Purchases</h4>
              <p>Use the Aave Faucet to get USDC on Avalanche Fuji:</p>
              <button
                onClick={() => window.open("https://faucet.aave.com/", "_blank")}
                className="faucet-btn"
              >
                💎 Aave Faucet
              </button>
              <p className="hint">Select "Avalanche Fuji" network and "USDC" token</p>
            </div>
          )}

          {step === 1 && (
            <div className="setup-action">
              <h4>Step 1: Add Avalanche Fuji Network</h4>
              <button
                onClick={addNetwork}
                className="action-btn primary"
              >
                ➕ Add Network to MetaMask
              </button>
            </div>
          )}

          {step === 2 && (
            <div className="setup-action">
              <h4>Step 2: Add USDC Token to MetaMask</h4>
              <button
                onClick={addUSDC}
                className="action-btn primary"
              >
                ➕ Add USDC Token
              </button>
            </div>
          )}

          {step === 3 && (
            <div className="setup-action">
              <h4>Step 3: Get Test Tokens</h4>
              <p className="setup-instruction">
                Get testnet tokens using the faucets above, then refresh this page
              </p>
              <button
                onClick={checkRequirements}
                className="action-btn secondary"
              >
                🔄 Refresh & Check
              </button>
            </div>
          )}
        </div>
      )}

      {/* Success State */}
      {ready_to_purchase && (
        <div className="success-section">
          <h3>✅ All Set!</h3>
          <div className="success-message">
            <p>Your wallet is ready for autonomous commerce:</p>
            <ul>
              <li>✓ Avalanche Fuji network configured</li>
              <li>✓ USDC token added</li>
              <li>✓ Sufficient AVAX for gas</li>
              <li>✓ Sufficient USDC for purchases</li>
            </ul>
          </div>
          <button
            onClick={() => onReady?.(true)}
            className="action-btn success"
          >
            🚀 Start Shopping
          </button>
        </div>
      )}

      {/* Refresh Button */}
      {!ready_to_purchase && (
        <div className="refresh-section">
          <button
            onClick={checkRequirements}
            disabled={loading}
            className="refresh-btn"
          >
            🔄 Refresh Status
          </button>
        </div>
      )}

      {error && (
        <div className="error-message">
          <p>Error: {error}</p>
        </div>
      )}
    </div>
  );
};

export default WalletSetup;
